import pandas as pd, numpy as np
train = pd.read_csv('train.csv')
test = pd.read_csv('test.csv')
feature_cols = [c for c in train.columns if c != 'target']
X = train[feature_cols].values
y = train['target'].values
X_test = test[feature_cols].values
y_test = test['target'].values

# Build depth-2 decision tree using information gain
def entropy(y):
    if len(y) == 0: return 0
    p = y.mean()
    if p == 0 or p == 1: return 0
    return -p*np.log2(p) - (1-p)*np.log2(1-p)

def best_split(X, y):
    best_gain = -1
    best_j = None
    best_t = None
    H = entropy(y)
    for j in range(X.shape[1]):
        vals = np.sort(np.unique(X[:, j]))
        thresholds = (vals[:-1] + vals[1:]) / 2
        for t in thresholds:
            left = y[X[:, j] <= t]
            right = y[X[:, j] > t]
            if len(left) < 3 or len(right) < 3:
                continue
            gain = H - (len(left)*entropy(left) + len(right)*entropy(right))/len(y)
            if gain > best_gain:
                best_gain = gain
                best_j = j
                best_t = t
    return best_j, best_t

# Build tree
j1, t1 = best_split(X, y)
print(f'Root: {feature_cols[j1]} <= {t1:.3f}')

left_mask = X[:, j1] <= t1
right_mask = ~left_mask
print(f'  Left: n={left_mask.sum()}, class 1 rate={y[left_mask].mean():.3f}')
print(f'  Right: n={right_mask.sum()}, class 1 rate={y[right_mask].mean():.3f}')

# Split left
j2l, t2l = best_split(X[left_mask], y[left_mask])
if j2l is not None:
    print(f'  Left split: {feature_cols[j2l]} <= {t2l:.3f}')

# Split right
j2r, t2r = best_split(X[right_mask], y[right_mask])
if j2r is not None:
    print(f'  Right split: {feature_cols[j2r]} <= {t2r:.3f}')

# Make predictions with depth-2 tree
def predict_tree(x):
    if x[j1] <= t1:
        if j2l is not None and x[j2l] <= t2l:
            return int(y[left_mask & (X[:, j2l] <= t2l)].mean() > 0.5)
        elif j2l is not None:
            return int(y[left_mask & (X[:, j2l] > t2l)].mean() > 0.5)
        else:
            return int(y[left_mask].mean() > 0.5)
    else:
        if j2r is not None and x[j2r] <= t2r:
            return int(y[right_mask & (X[:, j2r] <= t2r)].mean() > 0.5)
        elif j2r is not None:
            return int(y[right_mask & (X[:, j2r] > t2r)].mean() > 0.5)
        else:
            return int(y[right_mask].mean() > 0.5)

# Train accuracy
train_preds = [predict_tree(X[i]) for i in range(len(X))]
print(f'Train acc: {(np.array(train_preds) == y).mean():.3f}')

# Test accuracy
test_preds = [predict_tree(X_test[i]) for i in range(len(X_test))]
print(f'Test acc: {(np.array(test_preds) == y_test).mean():.3f}')

# LOO-CV for depth-1 tree (single stump using best_split)
correct = 0
for i in range(len(y)):
    mask = np.ones(len(y), dtype=bool)
    mask[i] = False
    jj, tt = best_split(X[mask], y[mask])
    left = y[mask][X[mask][:, jj] <= tt]
    right = y[mask][X[mask][:, jj] > tt]
    if X[i, jj] <= tt:
        pred = int(left.mean() > 0.5)
    else:
        pred = int(right.mean() > 0.5)
    if pred == y[i]:
        correct += 1
print(f'Depth-1 LOO: {correct/len(y):.3f}')
"

