import pandas as pd, numpy as np
train = pd.read_csv('train.csv')
feature_cols = [c for c in train.columns if c != 'target']
X = train[feature_cols].values
y = train['target'].values

# LOO-CV for weighted stump ensemble
for min_acc in [0.55, 0.60, 0.62, 0.65]:
    for n in [3, 5, 7, 10, 15, 50]:
        correct = 0
        for i in range(len(y)):
            mask = np.ones(len(y), dtype=bool)
            mask[i] = False
            Xt = X[mask]
            yt = y[mask]

            stumps = []
            for j in range(Xt.shape[1]):
                vals = np.sort(np.unique(Xt[:, j]))
                thresholds = (vals[:-1] + vals[1:]) / 2
                best_acc = 0
                best_t = None
                best_dir = None
                for t in thresholds:
                    for direction in [1, -1]:
                        if direction == 1:
                            preds = (Xt[:, j] > t).astype(int)
                        else:
                            preds = (Xt[:, j] <= t).astype(int)
                        acc = (preds == yt).mean()
                        if acc > best_acc:
                            best_acc = acc
                            best_t = t
                            best_dir = direction
                if best_acc > min_acc:
                    stumps.append((j, best_t, best_dir, best_acc))

            stumps.sort(key=lambda x: -x[3])
            top = stumps[:n]

            if len(top) == 0:
                pred = int(yt.mean() > 0.5)
            else:
                votes = 0
                total_w = 0
                for j2, t2, d2, acc2 in top:
                    w = acc2 - 0.5
                    if d2 == 1:
                        votes += w * int(X[i, j2] > t2)
                    else:
                        votes += w * int(X[i, j2] <= t2)
                    total_w += w
                pred = int(votes > total_w / 2)

            if pred == y[i]:
                correct += 1

        loo_acc = correct / len(y)
        if loo_acc > 0.55:
            print(f'min_acc={min_acc}, n={n}: LOO={loo_acc:.3f}')
" 2>&1

